"""PL-02 step 4: annualize the volatility."""

from math import sqrt

from risk.types import VolSeries


def annualize(vol: VolSeries, periods_per_year: int = 252) -> VolSeries:
    """Each daily volatility times the square root of `periods_per_year` (RISK-03).

    Gaps (None) stay in place. Raises ValueError if `vol` is already annualized.
    """
    if vol.annualized:
        raise ValueError("volatility is already annualized")
    scale = sqrt(periods_per_year)
    values = {
        ticker: tuple(None if v is None else v * scale for v in series)
        for ticker, series in vol.values.items()
    }
    return VolSeries(returns=vol.returns, window=vol.window, annualized=True, values=values)
